pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Relative progress through the stream
    let progress = step_index as f64 / total_items as f64;

    // Ratio of remaining space after placing the item
    let residual_ratio = post_residual as f64 / bin_capacity as f64;

    // Start with the raw residual
    let mut score = post_residual as f64;

    // Penalise large gaps quadratically – keeps the heuristic sensitive to dead space
    score += residual_ratio.powi(2) * 120.0;

    // Give a small bonus for almost perfect packing
    if residual_ratio < 0.02 {
        score -= 30.0;
    }

    // New‑bin handling: discourage opening a new bin early,
    // but allow it if many bins are already open or we’re late in the stream
    if bin_residual == bin_capacity {
        let new_bin_penalty =
            (open_bins_count as f64).ln() * 1.2 + progress * 15.0;
        score += new_bin_penalty;
        if step_index > total_items * 7 / 10 {
            score += 20.0;
        }
    }

    // Look‑ahead: if the next item will not fit, the current gap is bad
    if next_item_size > 0 {
        if next_item_size > post_residual {
            let diff = next_item_size as f64 - post_residual as f64;
            score += 25.0 + diff / bin_capacity as f64 * 12.0;
        } else {
            // encourage bins that also fit the next item
            score -= 3.0;
        }
    }

    // Reward a unique fit (only one bin can accept the item)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalise deviation from the mean residual – keeps bins balanced
    let mean_diff = (bin_residual as f64 - mean_residual).abs();
    score += mean_diff * 0.06;

    // Extra penalty for a large residual in an already‑filled bin
    if bin_residual > (mean_residual as u32 + 8) && bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.03;
    }

    // Prefer existing bins when many are open
    if open_bins_count > 25 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    // Tighten packing in the second half of the stream
    if step_index > total_items / 2 {
        score += residual_ratio * 18.0;
    }

    score
}

