    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the remaining space after placing the item.
    let mut score = post_residual as f64;

    // 1. Penalise tiny gaps heavily.
    if post_residual < 5 {
        score += 200.0;
    } else if post_residual < 10 {
        score += 100.0;
    } else if post_residual < 20 {
        score += 50.0;
    }

    // 2. New‑bin candidate: increase penalty with number of open bins
    // and with progress through the stream.
    if bin_residual == bin_capacity {
        let bin_penalty = (open_bins_count as f64).sqrt() * 0.7;
        score += bin_penalty;
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.85 {
            score += 40.0;
        }
    }

    // 3. Look‑ahead: if the next item does not fit in the remaining space,
    // the current gap is undesirable. The penalty grows with the size of the
    // uncovered space relative to the bin capacity.
    if next_item_size > 0 && next_item_size > post_residual {
        let diff = next_item_size as f64 - post_residual as f64;
        score += 30.0 + (diff / bin_capacity as f64) * 20.0;
    }

    // 4. Reward an existing bin that is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Encourage bins whose residuals are close to the mean residual.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Extra penalty for very large gaps in already‑filled bins.
    if bin_residual > (mean_residual as u32 + 10) && bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    // 7. Prefer using existing bins when many are open.
    if open_bins_count > 20 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // 8. Small bonus if the bin can also accommodate the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // 9. During the second half of the stream, tighten packing further.
    if step_index > total_items / 2 {
        let tight_factor = post_residual as f64 / bin_capacity as f64;
        score += tight_factor * 30.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: remaining space after placement
    let mut score = post_residual as f64;

    // 1. Heavy penalty for tiny gaps
    if post_residual < 5 {
        score += 200.0;
    } else if post_residual < 10 {
        score += 100.0;
    } else if post_residual < 20 {
        score += 50.0;
    }

    // 2. New-bin candidate penalty (moderate)
    if bin_residual == bin_capacity {
        let base_penalty = (open_bins_count as f64).sqrt() * 0.5;
        let mut bin_penalty = base_penalty;
        // Reduce penalty if many bins already open
        if open_bins_count > 50 {
            bin_penalty *= 0.3;
        }
        score += bin_penalty;
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.90 {
            score += 50.0;
        }
        // Additional penalty if mean residual is low (high fragmentation)
        if mean_residual < 10.0 {
            score += 20.0;
        }
    }

    // 3. Look‑ahead penalty/bonus for next item
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // next item would not fit after this placement
            let diff = next_item_size as f64 - post_residual as f64;
            score += 20.0 + (diff / bin_capacity as f64) * 20.0;
        } else {
            // next item fits in the residual
            score -= 7.0;
            // Bonus if the bin can accommodate both items immediately
            if bin_residual >= item_size + next_item_size {
                score -= 12.0;
            }
        }
        // Extra check: if the bin can hold current + next item but not yet considered
        if bin_residual >= item_size + next_item_size {
            score -= 10.0;
        }
    }

    // 4. Reward a unique fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Encourage residuals near the mean
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Extra penalty for large gaps relative to mean
    if post_residual as f64 > mean_residual * 1.5 && bin_residual != bin_capacity {
        score += (post_residual as f64 - mean_residual * 1.5) * 0.2;
    }

    // 7. Prefer existing bins when many are open
    if open_bins_count > 40 {
        score -= 10.0;
    } else if open_bins_count > 30 {
        score -= 8.0;
    } else if open_bins_count > 20 {
        score -= 4.0;
    }

    // 8. Tighten packing in the second half of the stream
    if step_index > total_items / 2 {
        let tight_factor = post_residual as f64 / bin_capacity as f64;
        score += tight_factor * 30.0;
    }

    // 9. Penalty when many bins can fit the item
    if fitting_bins_count > 5 {
        score += (fitting_bins_count - 5) as f64 * 0.4;
    }

    // 10. Early‑progress bonus
    let progress = step_index as f64 / total_items as f64;
    if progress < 0.20 {
        score -= 3.0;
    }

    // 11. Late‑stream penalty
    if progress > 0.95 {
        score += 8.0;
    }

    // 12. Residual‑to‑capacity ratio penalty
    let ratio = post_residual as f64 / bin_capacity as f64;
    if ratio > 0.75 && bin_residual != bin_capacity {
        score += (ratio - 0.75) * 120.0;
    }

    // 13. Next‑item size relative to bin capacity
    if next_item_size > 0 && next_item_size > bin_capacity * 9 / 10 {
        score += 4.0;
    }

    // 14. Bonus for bins with very high residual (potential for future packing)
    if bin_residual > bin_capacity * 9 / 10 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

